UNITS = [{'id': 'PEDS-U309', 'ch': 37, 'n': 1, 'title': 'Acute Kidney Injury — Definition, Staging & Biomarkers', 'sec': 'AKI definition and staging · p166', 'qs': ['PEDS-C37-001', 'PEDS-C37-002', 'PEDS-C37-003', 'PEDS-C37-004', 'PEDS-C37-005', 'PEDS-C37-006', 'PEDS-C37-007', 'PEDS-C37-008', 'PEDS-C37-009', 'PEDS-C37-010', 'PEDS-C37-011', 'PEDS-C37-012', 'PEDS-C37-013', 'PEDS-C37-014', 'PEDS-C37-015', 'PEDS-C37-016', 'PEDS-C37-017', 'PEDS-C37-018', 'PEDS-C37-019', 'PEDS-C37-020', 'PEDS-C37-021', 'PEDS-C37-022'], 'guide': 'AKI is acute impairment of kidney function, diagnosed by a creatinine rise or oliguria. Learn the KDIGO-style stage thresholds, Schwartz eGFR and the limitations of serum creatinine alongside newer biomarkers.'}, {'id': 'PEDS-U310', 'ch': 37, 'n': 2, 'title': 'AKI — Etiology & Management', 'sec': 'AKI etiology and management · p167', 'qs': ['PEDS-C37-023', 'PEDS-C37-024', 'PEDS-C37-025', 'PEDS-C37-026', 'PEDS-C37-027', 'PEDS-C37-028', 'PEDS-C37-029', 'PEDS-C37-030', 'PEDS-C37-031', 'PEDS-C37-032', 'PEDS-C37-033', 'PEDS-C37-034', 'PEDS-C37-035', 'PEDS-C37-036', 'PEDS-C37-037', 'PEDS-C37-038', 'PEDS-C37-039', 'PEDS-C37-040', 'PEDS-C37-041', 'PEDS-C37-042', 'PEDS-C37-043', 'PEDS-C37-044', 'PEDS-C37-045', 'PEDS-C37-046', 'PEDS-C37-047', 'PEDS-C37-048', 'PEDS-C37-049', 'PEDS-C37-050', 'PEDS-C37-051'], 'guide': 'Classify AKI into pre-renal hypoperfusion, renal parenchymal causes and post-renal obstruction. Restore perfusion in pre-renal AKI; restrict fluid in renal AKI and treat important electrolyte/acid-base complications safely.'}, {'id': 'PEDS-U311', 'ch': 37, 'n': 3, 'title': 'Hemolytic Uremic Syndrome', 'sec': 'HUS · p167–168', 'qs': ['PEDS-C37-052', 'PEDS-C37-053', 'PEDS-C37-054', 'PEDS-C37-055', 'PEDS-C37-056', 'PEDS-C37-057', 'PEDS-C37-058', 'PEDS-C37-059', 'PEDS-C37-060', 'PEDS-C37-061', 'PEDS-C37-062', 'PEDS-C37-063', 'PEDS-C37-064', 'PEDS-C37-065', 'PEDS-C37-066', 'PEDS-C37-067', 'PEDS-C37-068', 'PEDS-C37-069', 'PEDS-C37-070', 'PEDS-C37-071'], 'guide': 'Typical diarrhea-positive HUS follows Shiga toxin from Shigella dysenteriae or EHEC O157:H7. Endothelial injury drives microangiopathic hemolysis and renal injury; distinguish complement-mediated diarrhea-negative HUS and treat appropriately.'}, {'id': 'PEDS-U312', 'ch': 37, 'n': 4, 'title': 'Chronic Kidney Disease — Definition & Staging', 'sec': 'CKD definition and staging · p168', 'qs': ['PEDS-C37-072', 'PEDS-C37-073', 'PEDS-C37-074', 'PEDS-C37-075', 'PEDS-C37-076', 'PEDS-C37-077', 'PEDS-C37-078', 'PEDS-C37-079', 'PEDS-C37-080', 'PEDS-C37-081', 'PEDS-C37-082', 'PEDS-C37-083'], 'guide': 'CKD is persistent functional decline or renal abnormality for at least three months. Know the GFR bands, including initial hyperfiltration, and link advanced disease to its complications.'}, {'id': 'PEDS-U313', 'ch': 37, 'n': 5, 'title': 'CKD — Causes, Medical Management & Complications', 'sec': 'CKD causes and complications · p169', 'qs': ['PEDS-C37-084', 'PEDS-C37-085', 'PEDS-C37-086', 'PEDS-C37-087', 'PEDS-C37-088', 'PEDS-C37-089', 'PEDS-C37-090', 'PEDS-C37-091', 'PEDS-C37-092', 'PEDS-C37-093', 'PEDS-C37-094', 'PEDS-C37-095', 'PEDS-C37-096', 'PEDS-C37-097', 'PEDS-C37-098', 'PEDS-C37-099', 'PEDS-C37-100', 'PEDS-C37-101', 'PEDS-C37-102', 'PEDS-C37-103'], 'guide': 'Congenital anomalies are the most common CKD cause. Correct reversible structural disease surgically; otherwise support growth and prevent/treat anemia, mineral bone disease, short stature and hypertension.'}, {'id': 'PEDS-U314', 'ch': 37, 'n': 6, 'title': 'Kidney Replacement Therapy', 'sec': 'Kidney replacement therapy · p170', 'qs': ['PEDS-C37-104', 'PEDS-C37-105', 'PEDS-C37-106', 'PEDS-C37-107', 'PEDS-C37-108', 'PEDS-C37-109', 'PEDS-C37-110', 'PEDS-C37-111', 'PEDS-C37-112', 'PEDS-C37-113', 'PEDS-C37-114'], 'guide': 'Progressive CKD refractory to medical therapy needs KRT at GFR <12. Dialysis is accessible while awaiting a donor; renal transplantation is definitive. Compare home peritoneal dialysis with hospital hemodialysis.'}]
